export function resolveResonanceLocalizedMessages(candidate) {
    return Object.freeze({
        ...ENGLISH_RESONANCE_MESSAGES,
        ...nonEmptyMessagesRead(candidate),
    });
}
function nonEmptyMessagesRead(candidate) {
    if (!candidate)
        return {};
    return Object.fromEntries(Object.entries(candidate).filter(([, value]) => (typeof value === "string" && value.trim().length > 0)));
}
const runtimeMessages = globalThis.ToneLabResonanceMessages;
export const resonanceLocalizedMessages = resolveResonanceLocalizedMessages(runtimeMessages);
